{
  "groups": [
    {
      "group_id": "vulnerable_renters_or_second_home",
      "rule": "occupancy_type != 'owner_occupied'",
      "rationale": "Non-owner occupied properties represent investment or rental risks with different sensitivity to interest rate fluctuations."
    },
    {
      "group_id": "high_leverage_variable_rate",
      "rule": "rate_type == 'variable' and credit_utilization_pct >= 40.0",
      "rationale": "Borrowers with variable rates and high credit utilization are highly sensitive to payment shock and liquidity constraints."
    },
    {
      "group_id": "low_equity_distressed",
      "rule": "insured_flag == True and credit_score_band in ['below_600', '600_659']",
      "rationale": "Insured borrowers with low credit scores face limited refinancing options and higher retention risk."
    },
    {
      "group_id": "stable_long_term_owners",
      "rule": "td_tenure_months >= 84 and rate_type == 'fixed'",
      "rationale": "Long-tenure fixed-rate borrowers typically exhibit higher loyalty but may be targeted by competitors upon mortgage maturity."
    },
    {
      "group_id": "high_income_prime_families",
      "rule": "household_income_cad >= 150000 and n_children >= 2",
      "rationale": "Affluent families with high debt obligations prioritize convenience and are less likely to shop around aggressively."
    },
    {
      "group_id": "recent_high_rate_fixers",
      "rule": "origination_year >= 2022 and rate_type == 'fixed' and mortgage_rate_pct >= 4.0",
      "rationale": "Borrowers who locked in high rates recently face potential payment relief upon renewal and are prime targets for retention offers."
    },
    {
      "group_id": "liquidity_constrained_employed",
      "rule": "has_savings == False and employment_status == 'employed'",
      "rationale": "Employed borrowers without cash buffers are susceptible to churn if they perceive a better monthly cash flow opportunity elsewhere."
    }
  ]
}
